1	'use strict'
2	
3	const http = require('node:http')
4	const https = require('node:https')
5	const http2 = require('node:http2')
6	const dns = require('node:dns')
7	const os = require('node:os')
8	
9	const { kState, kOptions, kServerBindings, kHttp2ServerSessions } = require('./symbols')
10	const { FSTWRN003 } = require('./warnings')
11	const { onListenHookRunner } = require('./hooks')
12	const {
13	  FST_ERR_REOPENED_CLOSE_SERVER,
14	  FST_ERR_REOPENED_SERVER,
15	  FST_ERR_LISTEN_OPTIONS_INVALID,
16	  FST_ERR_FORCE_CLOSE_CONNECTIONS_IDLE_NOT_AVAILABLE
17	} = require('./errors')
18	const noopSet = require('./noop-set')
19	const PonyPromise = require('./promise')
20	
21	module.exports.createServer = createServer
22	
23	function defaultResolveServerListeningText (address) {
24	  return `Server listening at ${address}`
25	}
26	
27	function createServer (options, httpHandler) {
28	  const server = getServerInstance(options, httpHandler)
29	
30	  // `this` is the Fastify object
31	  function listen (
32	    listenOptions = { port: 0, host: 'localhost' },
33	    cb = undefined
34	  ) {
35	    if (typeof cb === 'function') {
36	      if (cb.constructor.name === 'AsyncFunction') {
37	        FSTWRN003('listen method')
38	      }
39	
40	      listenOptions.cb = cb
41	    }
42	    if (listenOptions.signal) {
43	      if (typeof listenOptions.signal.on !== 'function' && typeof listenOptions.signal.addEventListener !== 'function') {
44	        throw new FST_ERR_LISTEN_OPTIONS_INVALID('Invalid options.signal')
45	      }
46	
47	      // copy the current signal state
48	      this[kState].aborted = listenOptions.signal.aborted
49	
50	      if (this[kState].aborted) {
51	        return this.close()
52	      } else {
53	        const onAborted = () => {
54	          this[kState].aborted = true
55	          this.close()
56	        }
57	        listenOptions.signal.addEventListener('abort', onAborted, { once: true })
58	      }
59	    }
60	
61	    // If we have a path specified, don't default host to 'localhost' so we don't end up listening
62	    // on both path and host
63	    // See https://github.com/fastify/fastify/issues/4007
64	    let host
65	    if (listenOptions.path == null) {
66	      host = listenOptions.host ?? 'localhost'
67	    } else {
68	      host = listenOptions.host
69	    }
70	    if (!Object.hasOwn(listenOptions, 'host') ||
71	      listenOptions.host == null) {
72	      listenOptions.host = host
73	    }
74	    if (host === 'localhost') {
75	      listenOptions.cb = (err, address) => {
76	        if (err) {
77	          // the server did not start
78	          cb(err, address)
79	          return
80	        }
81	
82	        multipleBindings.call(this, server, httpHandler, options, listenOptions, () => {
83	          this[kState].listening = true
84	          cb(null, address)
85	          onListenHookRunner(this)
86	        })
87	      }
88	    } else {
89	      listenOptions.cb = (err, address) => {
90	        // the server did not start
91	        if (err) {
92	          cb(err, address)
93	          return
94	        }
95	        this[kState].listening = true
96	        cb(null, address)
97	        onListenHookRunner(this)
98	      }
99	    }
100	
101	    // https://github.com/nodejs/node/issues/9390
102	    // If listening to 'localhost', listen to both 127.0.0.1 or ::1 if they are available.
103	    // If listening to 127.0.0.1, only listen to 127.0.0.1.
104	    // If listening to ::1, only listen to ::1.
105	
106	    if (cb === undefined) {
107	      const listening = listenPromise.call(this, server, listenOptions)
108	      return listening.then(address => {
109	        const { promise, resolve } = PonyPromise.withResolvers()
110	        if (host === 'localhost') {
111	          multipleBindings.call(this, server, httpHandler, options, listenOptions, () => {
112	            this[kState].listening = true
113	            resolve(address)
114	            onListenHookRunner(this)
115	          })
116	        } else {
117	          resolve(address)
118	          onListenHookRunner(this)
119	        }
120	        return promise
121	      })
122	    }
123	
124	    this.ready(listenCallback.call(this, server, listenOptions))
125	  }
126	
127	  const serverHasCloseAllConnections = typeof server.closeAllConnections === 'function'
128	  const serverHasCloseIdleConnections = typeof server.closeIdleConnections === 'function'
129	  const serverHasCloseHttp2Sessions = typeof server.closeHttp2Sessions === 'function'
130	
131	  let forceCloseConnections = options.forceCloseConnections
132	  if (forceCloseConnections === 'idle' && !serverHasCloseIdleConnections) {
133	    throw new FST_ERR_FORCE_CLOSE_CONNECTIONS_IDLE_NOT_AVAILABLE()
134	  } else if (typeof forceCloseConnections !== 'boolean') {
135	    /* istanbul ignore next: only one branch can be valid in a given Node.js version */
136	    forceCloseConnections = serverHasCloseIdleConnections ? 'idle' : false
137	  }
138	
139	  const keepAliveConnections = !serverHasCloseAllConnections && forceCloseConnections === true ? new Set() : noopSet()
140	
141	  return {
142	    server,
143	    listen,
144	    forceCloseConnections,
145	    serverHasCloseAllConnections,
146	    serverHasCloseHttp2Sessions,
147	    keepAliveConnections
148	  }
149	}
150	
151	function multipleBindings (mainServer, httpHandler, serverOpts, listenOptions, onListen) {
152	  // the main server is started, we need to start the secondary servers
153	  this[kState].listening = false
154	
155	  // let's check if we need to bind additional addresses
156	  dns.lookup(listenOptions.host, { all: true }, (dnsErr, addresses) => {
157	    if (dnsErr || this[kState].aborted) {
158	      // not blocking the main server listening
159	      // this.log.warn('dns.lookup error:', dnsErr)
160	      onListen()
161	      return
162	    }
163	
164	    const isMainServerListening = mainServer.listening && serverOpts.serverFactory
165	
166	    let binding = 0
167	    let bound = 0
168	    if (!isMainServerListening) {
169	      const primaryAddress = mainServer.address()
170	      for (const adr of addresses) {
171	        if (adr.address !== primaryAddress.address) {
172	          binding++
173	          const secondaryOpts = Object.assign({}, listenOptions, {
174	            host: adr.address,
175	            port: primaryAddress.port,
176	            cb: (_ignoreErr) => {
177	              bound++
178	
179	              if (!_ignoreErr) {
180	                this[kServerBindings].push(secondaryServer)
181	              }
182	
183	              if (bound === binding) {
184	                // regardless of the error, we are done
185	                onListen()
186	              }
187	            }
188	          })
189	
190	          const secondaryServer = getServerInstance(serverOpts, httpHandler)
191	          const closeSecondary = () => {
192	            // To avoid falling into situations where the close of the
193	            // secondary server is triggered before the preClose hook
194	            // is done running, we better wait until the main server is closed.
195	            // No new TCP connections are accepted
196	            // We swallow any error from the secondary server
197	            secondaryServer.close(() => {})
198	            if (typeof secondaryServer.closeAllConnections === 'function' && serverOpts.forceCloseConnections === true) {
199	              secondaryServer.closeAllConnections()
200	            }
201	            if (typeof secondaryServer.closeHttp2Sessions === 'function') {
202	              secondaryServer.closeHttp2Sessions()
203	            }
204	          }
205	
206	          secondaryServer.on('upgrade', mainServer.emit.bind(mainServer, 'upgrade'))
207	          mainServer.on('unref', closeSecondary)
208	          mainServer.on('close', closeSecondary)
209	          mainServer.on('error', closeSecondary)
210	          this[kState].listening = false
211	          listenCallback.call(this, secondaryServer, secondaryOpts)()
212	        }
213	      }
214	    }
215	    // no extra bindings are necessary
216	    if (binding === 0) {
217	      onListen()
218	      return
219	    }
220	
221	    // in test files we are using unref so we need to propagate the unref event
222	    // to the secondary servers. It is valid only when the user is
223	    // listening on localhost
224	    const originUnref = mainServer.unref
225	    mainServer.unref = function () {
226	      originUnref.call(mainServer)
227	      mainServer.emit('unref')
228	    }
229	  })
230	}
231	
232	function listenCallback (server, listenOptions) {
233	  const wrap = (err) => {
234	    server.removeListener('error', wrap)
235	    server.removeListener('listening', wrap)
236	    if (!err) {
237	      const address = logServerAddress.call(
238	        this,
239	        server,
240	        listenOptions.listenTextResolver || defaultResolveServerListeningText
241	      )
242	      listenOptions.cb(null, address)
243	    } else {
244	      this[kState].listening = false
245	      listenOptions.cb(err, null)
246	    }
247	  }
248	
249	  return (err) => {
250	    if (err != null) return listenOptions.cb(err)
251	
252	    if (this[kState].listening && this[kState].closing) {
253	      return listenOptions.cb(new FST_ERR_REOPENED_CLOSE_SERVER(), null)
254	    }
255	    if (this[kState].listening) {
256	      return listenOptions.cb(new FST_ERR_REOPENED_SERVER(), null)
257	    }
258	
259	    server.once('error', wrap)
260	    if (!this[kState].closing) {
261	      server.once('listening', wrap)
262	      server.listen(listenOptions)
263	      this[kState].listening = true
264	    }
265	  }
266	}
267	
268	function listenPromise (server, listenOptions) {
269	  if (this[kState].listening && this[kState].closing) {
270	    return Promise.reject(new FST_ERR_REOPENED_CLOSE_SERVER())
271	  }
272	  if (this[kState].listening) {
273	    return Promise.reject(new FST_ERR_REOPENED_SERVER())
274	  }
275	
276	  return this.ready().then(() => {
277	    // skip listen when aborted during ready
278	    if (this[kState].aborted) return
279	
280	    const { promise, resolve, reject } = PonyPromise.withResolvers()
281	
282	    const errEventHandler = (err) => {
283	      cleanup()
284	      this[kState].listening = false
285	      reject(err)
286	    }
287	    const listeningEventHandler = () => {
288	      cleanup()
289	      this[kState].listening = true
290	      resolve(logServerAddress.call(
291	        this,
292	        server,
293	        listenOptions.listenTextResolver || defaultResolveServerListeningText
294	      ))
295	    }
296	    function cleanup () {
297	      server.removeListener('error', errEventHandler)
298	      server.removeListener('listening', listeningEventHandler)
299	    }
300	    server.once('error', errEventHandler)
301	    server.once('listening', listeningEventHandler)
302	
303	    server.listen(listenOptions)
304	
305	    return promise
306	  })
307	}
308	
309	function getServerInstance (options, httpHandler) {
310	  if (options.serverFactory) {
311	    // User provided server instance
312	    return options.serverFactory(httpHandler, options)
