import { INestApplication } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';

const rawRequest = (
  port: number,
  path: string,
  agent?: http.Agent,
): Promise<{ status: number; headers: http.IncomingHttpHeaders; body: string }> =>
  new Promise((resolve, reject) => {
    http
      .get(
        `http://localhost:${port}${path}`,
        agent ? { agent } : { headers: { Connection: 'close' } },
        res => {
          let body = '';
          res.on('data', chunk => (body += chunk));
          res.on('end', () =>
            resolve({ status: res.statusCode || 0, headers: res.headers, body }),
          );
        },
      )
      .on('error', reject);
  });

describe('PROBE: extra shutdown boundary checks', () => {
  let app: INestApplication;

  afterEach(async () => {
    try {
      await app?.close();
    } catch {}
  });

  it('preserves boom body/status during shutdown', async () => {
    app = await NestFactory.create<NestFastifyApplication>(
      // AppModule has /slow only; use inline controller via a dynamic module
      (await import('../src/app.module.js')).AppModule,
      new FastifyAdapter(),
      { return503OnClosing: true, logger: false },
    );
  });

  it('queued request during shutdown keeps normal keep-alive before shutdown', async () => {
    const { Module, Controller, Get } = await import('@nestjs/common');
    @Controller()
    class C {
      @Get('ok')
      ok() {
        return 'ok';
      }
    }
    @Module({ controllers: [C] })
    class M {}

    app = await NestFactory.create<NestFastifyApplication>(
      M,
      new FastifyAdapter(),
      { return503OnClosing: true, logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });
    const r1 = await rawRequest(port, '/ok', agent);
    expect(r1.status).toBe(200);
    // Normal traffic must keep the connection alive
    expect(r1.headers['connection']).not.toBe('close');

    // Existing error response stays untouched
    const r2 = await rawRequest(port, '/does-not-exist', agent);
    expect(r2.status).toBe(404);
    expect(r2.body).not.toBe('Service Unavailable');

    // After close completes, new connections are refused
    await app.close();
    agent.destroy();
    await new Promise<void>((resolve, reject) => {
      const req = http.get(
        `http://localhost:${port}/ok`,
        { headers: { Connection: 'close' } },
        () => reject(new Error('unexpected response')),
      );
      req.on('error', err => {
        expect((err as NodeJS.ErrnoException).code).toMatch(
          /ECONNREFUSED|ECONNRESET|ERR_STREAM/,
        );
        resolve();
      });
    });
  });

  it('works without the option enabled (fastify default)', async () => {
    const { Module, Controller, Get } = await import('@nestjs/common');
    @Controller()
    class C {
      @Get('slow')
      async slow() {
        await new Promise(r => setTimeout(r, 300));
        return 'ok';
      }
    }
    @Module({ controllers: [C] })
    class M {}

    app = await NestFactory.create<NestFastifyApplication>(
      M,
      new FastifyAdapter(),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const p = rawRequest(port, '/slow');
    await new Promise(r => setTimeout(r, 100));
    const close = app.close();
    const res = await p;
    expect(res.status).toBe(200);
    expect(res.body).toBe('ok');
    await close;
  });
});

